import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() -> Result<(), AppError> {
    let a: conc.Channel<Int64> = conc.channel(0)
    let b: conc.Channel<Int64> = conc.channel(0)
    scope {
        let t1 = task effect io {
            let _ = a.send(1)
            let v = b.receive()
        }
        let t2 = task effect io {
            let _ = b.send(2)
            let v = a.receive()
        }
        let _ = t1.await()
        let _ = t2.await()
    }
    return Ok(())
}
